(()=>{
 const node=(tag,text='')=>{const e=document.createElement(tag);e.textContent=text;return e;},stamp=n=>new Date(n+10800000).toISOString().slice(0,16),time=n=>new Date(n).toLocaleTimeString('ru-RU',{timeZone:'Europe/Moscow',hour:'2-digit',minute:'2-digit'});
 const api=async(p,b)=>{const r=await fetch('/api/admin/'+p,{method:b?'POST':'GET',headers:b?{'Content-Type':'application/json'}:{},body:b?JSON.stringify(b):undefined});const d=await r.json();if(!r.ok)throw Error(d.error||'Не удалось загрузить календарь.');return d;};
 let root,date,days,equipment,grid,notice,busy=false;let saved={};try{saved=JSON.parse(sessionStorage.getItem('desk-calendar')||'{}');}catch{}
 const states={payment_pending:'Ожидает оплаты',departure_pending:'Ожидает отплытия',new:'Новая заявка',confirmed:'Подтверждена',cancelled:'Отменена',issued:'На воде',completed:'Завершена'};
 function walkVisible(r,begin,end,chosen){if(r.custom_json||chosen&&r.equipment!==chosen)return false;if(Number(r.departure_pending)===1){if(r.returned)return r.returned>=begin&&r.returned<end;return Date.parse(r.departed+':00+03:00')<end;}const departed=r.departed_at!=null&&Number.isFinite(Number(r.departed_at))?Number(r.departed_at):Date.parse(r.departed+':00+03:00');return departed<end&&(r.returned||Math.max(r.expected_return||0,end))>begin;}
 function walkLabel(r){if(Number(r.departure_pending)===1){if(r.returned)return'Отменено до отплытия';if(Number(r.initial_due)>0)return'Ожидает оплаты';return'Ожидает отплытия';}return r.initial_due<0?'Отменено до выдачи':r.initial_due>0?'Ожидает оплаты':r.returned?'Возвращено':'На воде';}
 async function load(){if(busy)return;busy=true;try{const d=await api('calendar?date='+date.value+'&days='+days.value);window.stationClose=d.close;grid.replaceChildren();notice.textContent=d.overdue.length?`Просроченных выдач: ${d.overdue.length}. До фактического возврата эта техника недоступна для новых броней.`:'';
  const chosen=equipment.value||saved.equipment||'';try{sessionStorage.setItem('desk-calendar',JSON.stringify({date:date.value,days:days.value,equipment:chosen}));}catch{}saved={};equipment.replaceChildren();const all=node('option','Вся техника');all.value='';equipment.append(all);for(const f of d.fleet){const o=node('option',f.label);o.value=f.id;equipment.append(o);}equipment.value=chosen;
  grid.className='calendar-grid'+(d.days===7?' week':'');for(let offset=0;offset<d.days;offset++){
   const day=new Date(Date.parse(d.date+'T00:00:00+03:00')+offset*86400000+10800000).toISOString().slice(0,10),column=node('section');column.className='calendar-day';column.append(node('h3',new Date(day+'T12:00:00+03:00').toLocaleDateString('ru-RU',{timeZone:'Europe/Moscow',weekday:'short',day:'numeric',month:'long'})));
   const begin=Date.parse(day+'T00:00:00+03:00'),end=begin+86400000;
   const rows=d.rows.filter(r=>r.start<end&&r.end>begin&&(!chosen||r.details.equipment===chosen)).sort((a,b)=>a.start-b.start||a.id-b.id);
   for(const r of rows){const b=r.details,card=node('article');card.className='calendar-booking '+(r.late?'late':r.state);card.append(node('strong',`${time(r.start)}–${time(r.end)} · № ${r.id}`),node('p',d.fleet.find(f=>f.id===b.equipment)?.label||b.equipment),node('p',`${b.name} · ${b.quantity} ${b.equipment==='big'?'чел.':'шт.'}`));const tel=node('a',b.phone);tel.href='tel:'+b.phone.replace(/[^+\d]/g,'');card.append(tel,node('p',states[r.state]||r.state));if(b.plan==='takeaway')card.append(node('small','С собой, возврат '+b.returnDate));if(r.late)card.append(node('b',`Опоздание более ${d.lateMinutes} мин`));if(r.availability)card.append(node('p','Свободно в интервале: '+r.availability.available));
    const action=(label,status,reason)=>{const btn=node('button',label);btn.type='button';btn.onclick=async()=>{if(status==='cancelled'&&!btn.dataset.confirm){btn.dataset.confirm='1';btn.textContent='Подтвердить действие';return;}btn.disabled=true;try{await api('inquiry-status',{id:r.id,revision:r.revision,status,...(reason?{reason}:{})});await load();document.querySelector('#refresh').click();}catch(e){notice.textContent=e.message;}finally{btn.disabled=false;}};card.append(btn);};
    if(r.status==='new')action('Подтвердить бронь','confirmed');if(['new','confirmed'].includes(r.status))action('Отменить бронь','cancelled');if(r.late)action('Не приехал — освободить','cancelled','no_show');
    if(r.status==='confirmed'){const issue=node('button','Выдать технику');issue.onclick=()=>window.issueBooking?.(r);card.append(issue);}window.smsInquiry?.(card,r);column.append(card);
   }
   const walkFold=node('details');walkFold.className='calendar-walks';const walks=d.rentals.filter(r=>walkVisible(r,begin,end,chosen));for(const r of walks){const card=node('article'),pending=Number(r.departure_pending)===1;card.className='calendar-booking '+(pending?(r.returned?'completed':'departure-pending'):r.returned?'completed':'issued');card.append(node('strong','Выдача № '+r.id+' · без онлайн-брони'),node('p',r.name+' · '+(d.fleet.find(f=>f.id===r.equipment)?.label||r.equipment)),node('p',pending?`${r.quantity} шт.`:`${r.quantity} шт. · ${time(r.departed_at!=null&&Number.isFinite(Number(r.departed_at))?Number(r.departed_at):Date.parse(r.departed+':00+03:00'))}–${time(r.expected_return)}`),node('p',walkLabel(r)));walkFold.append(card);}
   if(walks.length){walkFold.prepend(node('summary','Выдачи без брони · '+walks.length));column.append(walkFold);}
   if(!rows.length&&!walks.length)column.append(node('p','Нет броней и выдач.'));grid.append(column);
  }
 }catch(e){notice.textContent=e.message;}finally{busy=false;}}
 window.calendarLoad=()=>{
  if(root){if(root.contains(document.activeElement)&&document.activeElement.matches('input,select,textarea'))return;load();return;}root=node('section');root.className='panel';root.id='calendar';root.append(node('h2','Календарь бронирований'));const controls=node('div');controls.className='toolbar';
  function input(label,type){const l=node('label',label),i=node('input');i.type=type;l.append(i);controls.append(l);return i;}
  date=input('Дата','date');date.value=saved.date||stamp(Date.now()).slice(0,10);days=node('select');days.setAttribute('aria-label','Период календаря');for(const [v,t] of [[1,'День'],[7,'Неделя']]){const o=node('option',t);o.value=v;days.append(o);}days.value=saved.days||'1';equipment=node('select');equipment.setAttribute('aria-label','Техника в календаре');const refresh=node('button','Обновить календарь');refresh.onclick=load;date.onchange=load;days.onchange=load;equipment.onchange=load;controls.append(days,equipment,refresh);root.append(controls);notice=node('p');notice.setAttribute('role','status');grid=node('div');root.append(notice,grid);
  const check=node('details');check.append(node('summary','Проверить свободную технику на интервал'));const f=node('form');f.className='toolbar';const fields=[];for(const [label,value] of [['Начало',stamp(Date.now())],['Окончание',stamp(Date.now()+3600000)]]){const l=node('label',label),i=node('input');i.type='datetime-local';i.required=true;i.value=value;l.append(i);f.append(l);fields.push(i);}f.append(node('button','Проверить наличие'));const result=node('div');f.onsubmit=async e=>{e.preventDefault();try{const d=await api('availability?start='+encodeURIComponent(fields[0].value)+'&end='+encodeURIComponent(fields[1].value));result.replaceChildren(...d.items.map(a=>node('p',`${equipment.querySelector(`option[value="${a.equipment}"]`)?.textContent||a.equipment}: свободно ${a.available} из ${a.total}`)));}catch(e){result.textContent=e.message;}};check.append(f,result);root.append(check);
  document.querySelector('#calendar-slot').append(root);load();if(location.hash==='#calendar')root.scrollIntoView();
 };
})();
